import type { HTMLAttributes, ReactNode } from 'react'
import { Check, Minus, X } from 'lucide-react'
import { cn } from '@/lib/utils'

export type ComparisonValue = ReactNode | boolean | null
export type ComparisonColumn = { key: string; label: string; highlighted?: boolean }
export type ComparisonRow = { label: string; values: Record<string, ComparisonValue> }

export interface ComparisonTableProps extends Omit<HTMLAttributes<HTMLElement>, 'children'> {
  caption: string
  description?: string
  columns: readonly ComparisonColumn[]
  rows: readonly ComparisonRow[]
  firstColumnLabel?: string
  emptyMessage?: string
}

function Value({ value }: { value: ComparisonValue }) {
  if (value === true)
    return <Check className="mx-auto h-5 w-5 text-emerald-600" aria-label="Incluído" />
  if (value === false)
    return <X className="mx-auto h-5 w-5 text-muted-foreground" aria-label="Não incluído" />
  if (value == null)
    return <Minus className="mx-auto h-5 w-5 text-muted-foreground" aria-label="Não informado" />
  return <>{value}</>
}

export function ComparisonTable({
  caption,
  description,
  columns,
  rows,
  firstColumnLabel = 'Recurso',
  emptyMessage = 'Nenhum item para comparar.',
  className,
  ...props
}: ComparisonTableProps) {
  return (
    <section className={cn('w-full', className)} {...props}>
      <div className="mb-6">
        <h2 className="text-3xl font-bold tracking-tight md:text-4xl">{caption}</h2>
        {description ? <p className="mt-2 text-muted-foreground">{description}</p> : null}
      </div>
      {!columns.length || !rows.length ? (
        <p className="rounded-2xl border border-dashed p-8 text-center text-muted-foreground">
          {emptyMessage}
        </p>
      ) : (
        <div className="overflow-x-auto rounded-2xl border">
          <table className="w-full min-w-[40rem] border-collapse text-left text-sm">
            <caption className="sr-only">{caption}</caption>
            <thead className="bg-muted/60">
              <tr>
                <th scope="col" className="p-4 font-semibold">
                  {firstColumnLabel}
                </th>
                {columns.map((column) => (
                  <th
                    key={column.key}
                    scope="col"
                    className={cn(
                      'p-4 text-center font-semibold',
                      column.highlighted && 'bg-primary/10 text-primary',
                    )}
                  >
                    {column.label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => (
                <tr key={row.label} className="border-t transition-colors hover:bg-muted/30">
                  <th scope="row" className="p-4 font-medium">
                    {row.label}
                  </th>
                  {columns.map((column) => (
                    <td
                      key={column.key}
                      className={cn(
                        'p-4 text-center text-muted-foreground',
                        column.highlighted && 'bg-primary/5',
                      )}
                    >
                      <Value value={row.values[column.key]} />
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  )
}

'use client'

import Image from 'next/image'
import { A11y, Autoplay } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'

import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

import 'swiper/css'

export type LogoCarouselBandLogo = {
  name: string
  src: string
  href?: string
}

export type LogoCarouselBandProps = {
  logos: readonly LogoCarouselBandLogo[]
  title?: string
  eyebrow?: string
  description?: string
  monochrome?: boolean
  autoplayDelay?: number
  tone?: AccentTone
  className?: string
}

/** Faixa de logos em carrossel contínuo com divisórias e realce no hover. */
export function LogoCarouselBand({
  logos,
  title,
  eyebrow,
  description,
  monochrome = true,
  autoplayDelay = 2200,
  tone = 'glow',
  className,
}: LogoCarouselBandProps) {
  const t = getAccentTone(tone)
  const reduced = useReducedMotion()
  const light = tone === 'industrial'
  const items = logos.length < 8 ? [...logos, ...logos] : logos

  return (
    <section className={cn('relative overflow-hidden', t.section, className)}>
      <div className="container py-14 lg:py-16">
        {title ? (
          <EyebrowHeading
            tone={tone}
            eyebrow={eyebrow}
            title={title}
            description={description}
            layout="split"
            className="mb-10 lg:mb-12"
          />
        ) : null}

        <div
          className={cn(
            'overflow-hidden border',
            t.border,
            t.panel,
            tone === 'glow' && 'rounded-md',
          )}
        >
          <Swiper
            modules={[A11y, Autoplay]}
            spaceBetween={0}
            slidesPerView={2}
            loop
            speed={800}
            autoplay={reduced ? false : { delay: autoplayDelay, disableOnInteraction: false }}
            breakpoints={{
              640: { slidesPerView: 3 },
              768: { slidesPerView: 4 },
              1024: { slidesPerView: 6 },
            }}
          >
            {items.map((logo, index) => {
              const content = (
                <Image
                  src={logo.src}
                  alt={logo.name}
                  width={140}
                  height={64}
                  className={cn(
                    'max-h-12 w-auto object-contain opacity-70 transition-all duration-500 group-hover:opacity-100',
                    monochrome &&
                      (light ? 'grayscale group-hover:grayscale-0' : 'brightness-0 invert'),
                  )}
                />
              )
              return (
                <SwiperSlide key={`${logo.name}-${index}`}>
                  <div
                    className={cn(
                      'group flex h-28 items-center justify-center border-l px-6 transition-colors duration-300',
                      t.border,
                      light ? 'hover:bg-slate-50' : 'hover:bg-white/5',
                    )}
                  >
                    {logo.href ? (
                      <a
                        href={logo.href}
                        target="_blank"
                        rel="noopener noreferrer"
                        aria-label={logo.name}
                        className={t.focus}
                      >
                        {content}
                      </a>
                    ) : (
                      content
                    )}
                  </div>
                </SwiperSlide>
              )
            })}
          </Swiper>
        </div>
      </div>
    </section>
  )
}

import type { LucideIcon } from 'lucide-react'
import { cn } from '@/lib/utils'

export type FeatureGridProps = {
  title?: string
  description?: string
  features: Array<{ title: string; description: string; icon?: LucideIcon }>
  className?: string
}

export function FeatureGrid({ title, description, features, className }: FeatureGridProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'features-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2 id="features-title" className="text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        {description ? (
          <p className="mt-4 max-w-2xl text-lg text-muted-foreground">{description}</p>
        ) : null}
        <div
          className={cn(
            'mt-10 grid gap-5 md:grid-cols-2',
            features.length % 4 === 0 ? 'lg:grid-cols-4' : 'lg:grid-cols-3',
          )}
        >
          {features.map(({ title: featureTitle, description: featureDescription, icon: Icon }) => (
            <article
              key={featureTitle}
              className="rounded-2xl border bg-card p-6 text-card-foreground shadow-sm transition hover:-translate-y-1 hover:shadow-md"
            >
              {Icon ? (
                <span className="mb-5 flex h-11 w-11 items-center justify-center rounded-xl bg-primary/10 text-primary">
                  <Icon className="h-5 w-5" aria-hidden="true" />
                </span>
              ) : null}
              <h3 className="text-lg font-semibold">{featureTitle}</h3>
              <p className="mt-2 text-sm leading-6 text-muted-foreground">{featureDescription}</p>
            </article>
          ))}
        </div>
