          <h2
            id="pricing-title"
            className="mb-12 text-center text-3xl font-bold tracking-tight md:text-4xl"
          >
            {title}
          </h2>
        ) : null}
        <div className="mx-auto grid max-w-6xl items-stretch gap-6 lg:grid-cols-3">
          {plans.map((plan) => (
